    section={'file2':'الدروس الهجائية','file3':'العقيدة — الملف 3'}
    source_records={key:{'file':key[-1]+'.txt','sha256':sha256(raw_map[key]).hexdigest(),'githubCommit':COMMIT,'format':'notes' if key=='file2' else 'qa','prefix':prefix3 if key=='file3' else '', 'records':records} for key,records in record_map.items()}
    for sid,records in record_map.items():
        for r in records:
            if not r['answer']:continue
            q=dict(id=(2000000 if sid=='file2' else 3000000)+r['number'],book=sid,sourceId=sid,sourceFile=sid[-1]+'.txt',page=r['number'],sourceBlocks=[r['number']],lineStart=r['lineStart'],lineEnd=r['lineEnd'],
                sourceSha256=source_records[sid]['sha256'],section=section[sid],type='qa',prompt=r['prompt'],answer=r['answer'],options=[],kind='verbatim',variant='original',originalFormat='notes' if sid=='file2' else 'qa',
                origin='عنوان ونص مطابقان للملف؛ ليس سؤالًا مؤلفًا' if sid=='file2' else 'السؤال والجواب كما وردا حرفيًا',difficulty='أصلي',conceptKey=f'{sid}-block-{r["number"]}',nativeBlank=False,
                reviewOnly=sid=='file3' and r['number']==8,warning=CRITICAL if sid=='file3' and r['number']==8 else '')
            bank.append(q)
