        item=dict(id=(2100000 if sid=='file2' else 3100000)+sum(q['book']==sid for q in modified)+1,book=sid,sourceId=sid,sourceFile=sid[-1]+'.txt',page=refs[0],sourceBlocks=refs,
            lineStart=min(r['lineStart'] for r in rs),lineEnd=max(r['lineEnd'] for r in rs),sourceSha256=source_records[sid]['sha256'],
            section=section[sid],type=type,prompt=prompt,answer=a,options=[],kind='curated',variant='modified',originalFormat=None,
            origin='سؤال تحليلي معدّل من محتوى الملف نفسه فقط',difficulty='متقدم',conceptKey=f'{sid}-'+ '-'.join(map(str,refs)),nativeBlank=False,reviewOnly=False,warning='',
            evidence=[dict(block=r['number'],lineStart=r['lineStart'],lineEnd=r['lineEnd'],quote=r['answer']) for r in rs])
        item.update(extra);modified.append(item)
